// Extract call information from voice platform webhook
const callData = items[0].json;

// Initialize conversation context
const context = {
  callId: callData.call?.id || 'unknown',
  customerPhone: callData.call?.customer?.number || '',
  timestamp: new Date().toISOString(),
  conversationStage: 'greeting',
  customerInfo: {},
  cateringDetails: {},
  availableSlots: []
};

// Prepare menu information
const menuInfo = {
  packages: {
    small: {
      name: "Small Party Package (10-25 people)",
      description: "Perfect for intimate gatherings",
      basePrice: "$12-15 per person",
      includes: ["Choice of 2 meats", "2 sides", "Bread", "Sauce", "Setup"]
    },
    medium: {
      name: "Medium Party Package (25-50 people)",
      description: "Great for family reunions and events", 
      basePrice: "$11-14 per person",
      includes: ["Choice of 3 meats", "3 sides", "Bread", "Sauce", "Setup", "Serving utensils"]
    },
    large: {
      name: "Large Party Package (50-100 people)",
      description: "Perfect for corporate events",
      basePrice: "$10-13 per person", 
      includes: ["Choice of 4 meats", "4 sides", "Bread", "Sauce", "Full setup", "Serving staff option"]
    },
    xlarge: {
      name: "Extra Large Package (100+ people)",
      description: "For big celebrations and events",
      basePrice: "$9-12 per person",
      includes: ["All meat options", "5+ sides", "Full service", "Staff included", "Custom setup"]
    }
  },
  meats: ["Brisket", "Pulled Pork", "Ribs", "Chicken", "Sausage", "Turkey"],
  sides: ["Mac & Cheese", "Coleslaw", "Baked Beans", "Potato Salad", "Corn", "Green Beans"]
};

return [{
  json: {
    context,
    menuInfo,
    action: 'process_voice_input'
  }
}];

// Generate greeting response
const response = {
  message: "Hello! Thank you for calling 5 Alarm BBQ! I'm here to help you with catering for your special event. Can you tell me about your upcoming party - how many people are you expecting?",
  action: "collect_party_size",
  nextStage: "menu_inquiry"
};

return [{
  json: {
    ...items[0].json,
    response,
    context: {
      ...items[0].json.context,
      conversationStage: "menu_inquiry"
    }
  }
}];

// Process party size and suggest appropriate packages
const partySize = parseInt(items[0].json.userInput?.partySize) || 0;
const menuInfo = items[0].json.menuInfo;

let suggestedPackage;
let packageKey;

if (partySize <= 25) {
  packageKey = 'small';
  suggestedPackage = menuInfo.packages.small;
} else if (partySize <= 50) {
  packageKey = 'medium';
  suggestedPackage = menuInfo.packages.medium;
} else if (partySize <= 100) {
  packageKey = 'large';
  suggestedPackage = menuInfo.packages.large;
} else {
  packageKey = 'xlarge';
  suggestedPackage = menuInfo.packages.xlarge;
}

const response = {
  message: `Perfect! For ${partySize} people, I'd recommend our ${suggestedPackage.name}. This includes ${suggestedPackage.includes.join(', ')} at ${suggestedPackage.basePrice}. \n\nWe can also customize this based on your preferences. What type of event is this, and do you have any specific meat or side preferences?`,
  suggestedPackage,
  packageKey,
  action: "discuss_customization",
  nextStage: "package_selection"
};

return [{
  json: {
    ...items[0].json,
    response,
    context: {
      ...items[0].json.context,
      conversationStage: "package_selection",
      cateringDetails: {
        partySize,
        suggestedPackage: packageKey
      }
    }
  }
}];

// Handle package customization and move to booking details
const userPreferences = items[0].json.userInput || {};
const context = items[0].json.context;

const response = {
  message: `Excellent! I've noted your preferences. Now let's get your event details to check availability and complete your booking. \n\nCan you please provide:\n1. Your first and last name\n2. Your phone number\n3. Preferred event date\n4. Event location and if you need delivery\n5. Any special cooking requirements or dietary restrictions?\n\nI'll check our availability as we go.`,
  action: "collect_booking_info",
  nextStage: "booking_details"
};

return [{
  json: {
    ...items[0].json,
    response,
    context: {
      ...context,
      conversationStage: "booking_details",
      cateringDetails: {
        ...context.cateringDetails,
        preferences: userPreferences
      }
    }
  }
}];

// Process booking details and validate information
const userInput = items[0].json.userInput || {};
const context = items[0].json.context;

// Extract booking information
const bookingData = {
  firstName: userInput.firstName || '',
  lastName: userInput.lastName || '',
  phone: userInput.phone || context.customerPhone,
  eventDate: userInput.eventDate || '',
  eventLocation: userInput.eventLocation || '',
  serviceType: userInput.serviceType || 'pickup',
  specialRequirements: userInput.specialRequirements || '',
  address: userInput.address || ''
};

// Validate required fields
const missingFields = [];
if (!bookingData.firstName) missingFields.push('first name');
if (!bookingData.lastName) missingFields.push('last name');
if (!bookingData.phone) missingFields.push('phone number');
if (!bookingData.eventDate) missingFields.push('event date');

if (missingFields.length > 0) {
  const response = {
    message: `I still need a few more details: ${missingFields.join(', ')}. Can you provide those for me?`,
    action: "collect_missing_info",
    missingFields
  };

  return [{
    json: {
      ...items[0].json,
      response
    }
  }];
}

// All information collected - move to availability check
const response = {
  message: `Perfect! Let me check our availability for ${bookingData.eventDate} and prepare your booking summary.`,
  action: "check_availability",
  nextStage: "availability_check",
  bookingData
};

return [{
  json: {
    ...items[0].json,
    response,
    context: {
      ...context,
      conversationStage: "availability_check",
      customerInfo: bookingData,
      cateringDetails: {
        ...context.cateringDetails,
        bookingData
      }
    }
  }
}];

// Check availability against existing bookings
const bookingData = items[0].json.context.customerInfo;
const requestedDate = new Date(bookingData.eventDate);
const today = new Date();

// Check if date is in the future
if (requestedDate <= today) {
  return [{
    json: {
      ...items[0].json,
      availabilityResult: {
        available: false,
        reason: "past_date",
        message: "I notice that date has already passed. Could you provide a future date for your event?"
      }
    }
  }];
}

// Check if date is too soon (less than 1 week)
const daysDifference = Math.ceil((requestedDate - today) / (1000 * 60 * 60 * 24));
if (daysDifference < 7) {
  return [{
    json: {
      ...items[0].json,
      availabilityResult: {
        available: true,
        warning: "short_notice",
        message: "That's quite soon! We can usually accommodate short notice, but I'll need to have our catering manager confirm availability. ",
        daysDifference
      }
    }
  }];
}

// Simulate checking for conflicts (in real implementation, query your database)
const isAvailable = Math.random() > 0.1; // 90% chance available

if (isAvailable) {
  return [{
    json: {
      ...items[0].json,
      availabilityResult: {
        available: true,
        message: "Great news! We have availability for your requested date.",
        daysDifference
      }
    }
  }];
} else {
  return [{
    json: {
      ...items[0].json,
      availabilityResult: {
        available: false,
        reason: "booked",
        message: "I'm sorry, but we already have a booking for that date. Let me suggest some alternative dates around that time."
      }
    }
  }];
}

// Generate booking confirmation summary
const context = items[0].json.context;
const customerInfo = context.customerInfo;
const cateringDetails = context.cateringDetails;
const menuInfo = items[0].json.menuInfo;
const availabilityResult = items[0].json.availabilityResult;

// Get package details
const packageInfo = menuInfo.packages[cateringDetails.suggestedPackage] || menuInfo.packages.medium;

// Create booking summary
const bookingSummary = {
  customer: {
    name: `${customerInfo.firstName} ${customerInfo.lastName}`,
    phone: customerInfo.phone,
    email: customerInfo.email || ''
  },
  event: {
    date: customerInfo.eventDate,
    partySize: cateringDetails.partySize,
    location: customerInfo.eventLocation,
    serviceType: customerInfo.serviceType,
    address: customerInfo.address
  },
  catering: {
    package: packageInfo.name,
    estimatedCost: packageInfo.basePrice,
    specialRequirements: customerInfo.specialRequirements
  },
  bookingId: `BBQ-${Date.now()}`,
  status: 'pending_confirmation'
};

let confirmationMessage = `Perfect! Here's your booking summary:\n\n📅 Event Date: ${customerInfo.eventDate}\n👥 Party Size: ${cateringDetails.partySize} people\n🍖 Package: ${packageInfo.name}\n💰 Estimated Cost: ${packageInfo.basePrice}\n📍 Service: ${customerInfo.serviceType}`;

if (customerInfo.address) {
  confirmationMessage += `\n📮 Address: ${customerInfo.address}`;
}

if (availabilityResult.warning === 'short_notice') {
  confirmationMessage += `\n\n⚠️ Since this is short notice, I'll have our catering manager call you within 2 hours to confirm final details.`;
} else {
  confirmationMessage += `\n\nI'll have our catering manager call you within 24 hours to finalize all details, discuss final pricing, and confirm your booking.`;
}

confirmationMessage += `\n\nYour booking reference is: ${bookingSummary.bookingId}\n\nIs there anything else I can help you with regarding your catering needs?`;

const response = {
  message: confirmationMessage,
  action: "booking_confirmed",
  bookingSummary
};

return [{
  json: {
    ...items[0].json,
    response,
    bookingSummary,
    action: 'create_booking_record'
  }
}];

// Handle unavailable dates - suggest alternatives
const requestedDate = new Date(items[0].json.context.customerInfo.eventDate);
const availabilityResult = items[0].json.availabilityResult;

// Generate alternative dates (typically 2-3 options around requested date)
const alternatives = [];
for (let i = 1; i <= 3; i++) {
  const altDate = new Date(requestedDate);
  altDate.setDate(requestedDate.getDate() + (i * 7)); // Add weeks
  alternatives.push(altDate.toLocaleDateString());
}

let message;
if (availabilityResult.reason === 'past_date') {
  message = availabilityResult.message;
} else if (availabilityResult.reason === 'booked') {
  message = `${availabilityResult.message} Here are some alternative dates that work well: ${alternatives.join(', ')}. Do any of these work for your event?`;
}

const response = {
  message,
  alternatives,
  action: "request_new_date"
};

return [{
  json: {
    ...items[0].json,
    response
  }
}];
